import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as a,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const k=JSON.parse('{"title":"Kimi chat and Agent glossary","description":"No how-to. Split the things that share the words Kimi, Agent, Goal, and Project.","frontmatter":{"title":"Kimi chat and Agent glossary","description":"No how-to. Split the things that share the words Kimi, Agent, Goal, and Project.","domain":"product","tags":["chat"],"role":"glossary"},"headers":[],"relativePath":"products/kimi/kimi-glossary.md","filePath":"products/kimi/kimi-glossary.md","lastUpdated":1787110548000}'),i={name:"products/kimi/kimi-glossary.md"};function s(n,t,d,l,h,c){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="kimi-chat-and-agent-glossary" tabindex="-1">Kimi chat and Agent glossary <a class="header-anchor" href="#kimi-chat-and-agent-glossary" aria-label="Permalink to &quot;Kimi chat and Agent glossary&quot;">​</a></h1><p>No how-to. What the official pages mean — and what they are not. Product choice: <a href="./">learning map</a>. Internals: <a href="/tech/fundamentals/LLM.html">Learn LLM</a>.</p><h2 id="things-named-kimi" tabindex="-1">Things named Kimi <a class="header-anchor" href="#things-named-kimi" aria-label="Permalink to &quot;Things named Kimi&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>What it is</th><th>Where</th></tr></thead><tbody><tr><td><strong>Kimi</strong></td><td>All-in-one agentic AI workspace</td><td><a href="https://www.kimi.com/" target="_blank" rel="noreferrer">kimi.com</a></td></tr><tr><td><strong>Kimi Agent</strong></td><td>End-to-end autonomous assistant, K3 + 20+ tools</td><td><a href="https://www.kimi.com/agent" target="_blank" rel="noreferrer">kimi.com/agent</a></td></tr><tr><td><strong>Agent Swarm</strong></td><td>Up to 300 sub-agents in parallel</td><td><a href="https://www.kimi.com/agent-swarm" target="_blank" rel="noreferrer">kimi.com/agent-swarm</a></td></tr><tr><td><strong>Kimi Claw</strong></td><td>One-click cloud OpenClaw, optional chat channels</td><td><a href="https://www.kimi.com/bot" target="_blank" rel="noreferrer">kimi.com/bot</a></td></tr><tr><td><strong>Kimi Code</strong></td><td>Terminal and IDE coding agent</td><td><a href="/products/kimi-code/">Kimi Code</a></td></tr><tr><td><strong>Kimi Work</strong></td><td>Mac/Windows desktop knowledge-work agent (Work / Chat modes)</td><td><a href="https://www.kimi.com/products/kimi-work" target="_blank" rel="noreferrer">products/kimi-work</a></td></tr><tr><td><strong>Kimi WebBridge</strong></td><td>Browser extension for agents</td><td>Products page</td></tr><tr><td><strong>Kimi Platform</strong></td><td>Official model API</td><td><a href="https://platform.moonshot.cn/" target="_blank" rel="noreferrer">platform.moonshot.cn</a></td></tr><tr><td><strong>Kimi Business</strong></td><td>Enterprise</td><td>Help Center</td></tr><tr><td><strong>Kimi Plus</strong></td><td>Named on the plugins page as a chat surface without plugins yet</td><td><a href="https://www.kimi.com/help/features/plugins" target="_blank" rel="noreferrer">Plugins</a></td></tr><tr><td><strong>K2.6 / K3 / K3 Swarm</strong></td><td>Model / mode switch in the workspace</td><td>Model switch above the input</td></tr><tr><td><strong>Moonshot AI</strong></td><td>The company</td><td><a href="https://www.moonshot.cn/" target="_blank" rel="noreferrer">moonshot.cn</a></td></tr></tbody></table><h2 id="three-agent-scheduling-surfaces" tabindex="-1">Three Agent scheduling surfaces <a class="header-anchor" href="#three-agent-scheduling-surfaces" aria-label="Permalink to &quot;Three Agent scheduling surfaces&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Single Agent</th><th>Agent Swarm</th><th>Claw group chat</th></tr></thead><tbody><tr><td><strong>What</strong></td><td>One assistant plans and calls tools</td><td>One orchestrator, up to 300 sub-agents</td><td>Several Claws + Kimi Conductor</td></tr><tr><td><strong>Entry</strong></td><td><code>kimi.com/agent</code> or App <strong>K3</strong></td><td><code>kimi.com/agent-swarm</code> or <strong>K3 Swarm</strong></td><td><code>kimi.com/bot</code> → Start Group Chat</td></tr><tr><td><strong>Official emphasis</strong></td><td>20+ tools, Office / site deliverables</td><td>Scale out, no hand-written workflow</td><td>Cross-person, device, permission boundary</td></tr><tr><td><strong>Not</strong></td><td>Not Kimi Code</td><td>Not &quot;300 Claws&quot;</td><td>Not another name for Swarm</td></tr></tbody></table><p><strong>OpenClaw ≠ Kimi Claw.</strong> OpenClaw is the assistant you can self-host. Kimi Claw is Moonshot&#39;s deploy-or-link surface. A group chat can also invite someone else&#39;s OpenClaw as a Worker.</p><p><strong>OK Computer</strong> is the 2025-09-26 Agent-mode name on the official timeline. Current help leads with Kimi Agent / K3.</p><h2 id="goal-collisions" tabindex="-1">Goal collisions <a class="header-anchor" href="#goal-collisions" aria-label="Permalink to &quot;Goal collisions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Phrase</th><th>Where official</th><th>Not</th></tr></thead><tbody><tr><td>Goal / Goal Mode</td><td>Membership table (Allegretto+); project chats can use Goal</td><td>Not a free global toggle</td></tr><tr><td>Kimi Work Goal Mode</td><td>Work help</td><td>Not the same page as web chat</td></tr><tr><td>Kimi Code <code>/goal</code></td><td>Code CLI</td><td><strong>Not</strong> a kimi.com chat command</td></tr></tbody></table><p>There is no first-class &quot;Goal product&quot; URL. The family table keeps one row.</p><h2 id="two-projects" tabindex="-1">Two Projects <a class="header-anchor" href="#two-projects" aria-label="Permalink to &quot;Two Projects&quot;">​</a></h2><p>Official (<a href="https://www.kimi.com/help/features/project" target="_blank" rel="noreferrer">Projects</a>): the Kimi Work desktop app also has &quot;Projects&quot;; they are <strong>not connected and don&#39;t share data</strong>.</p><table tabindex="0"><thead><tr><th></th><th>kimi.com Projects</th><th>Kimi Work Projects</th></tr></thead><tbody><tr><td><strong>Job</strong></td><td>Persistent web workspace</td><td>Desktop task space</td></tr><tr><td><strong>This directory</strong></td><td>Tutorial / Cookbook</td><td>Map row only</td></tr></tbody></table><h2 id="credits-memory-skills-plugins" tabindex="-1">Credits, memory, Skills, plugins <a class="header-anchor" href="#credits-memory-skills-plugins" aria-label="Permalink to &quot;Credits, memory, Skills, plugins&quot;">​</a></h2><p><strong>Credit pool:</strong> membership features share one token-metered pool. Chat K2.6 is free. Kimi Code has a separate 5-hour / weekly rate limit. &quot;Agent credits 60&quot; is an official <em>approximate</em> typical-task conversion, not &quot;60 chat turns&quot;.</p><p><strong>Two plan-name systems:</strong> membership page Moderato / Allegretto / Allegro / Vivace (USD). Projects / Scheduled Tasks pages Free / Go / Pro / Max / Ultra. Cite each page. Do not merge.</p><p><strong>Memory:</strong> cross-chat preferences. Official: not used for training; no unauthorized private data by default. Project context injects global main memory; project instructions stay inside that project.</p><p><strong>Skills:</strong> on-demand knowledge packages. Official / recommended / open-source / custom. Type <code>/</code>.</p><p><strong>Plugins:</strong> third-party connectors. K3 / K3 Swarm and some scenarios; not Claw or Plus chats. Not the Kimi Code plugin config.</p><p><strong>Scheduled tasks:</strong> cloud on kimi.com; optional local on Kimi Work (app must be open).</p><h2 id="do-not-write-as-fact" tabindex="-1">Do not write as fact <a class="header-anchor" href="#do-not-write-as-fact" aria-label="Permalink to &quot;Do not write as fact&quot;">​</a></h2><ul><li>&quot;Kimi is Kimi Code&quot;</li><li>&quot;Typing <code>/goal</code> on the web equals CLI Goal&quot;</li><li>&quot;Moderato is Go&quot;</li><li>&quot;Claw group chat = Agent Swarm&quot;</li><li>Code install scripts as this directory&#39;s quickstart</li><li>CNY prices (this research did not treat a separate CN price page as SSOT)</li></ul><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./">Learning map</a></li><li><a href="./kimi.html">Tutorial</a></li><li><a href="./kimi-cookbook.html">Cookbook</a></li><li><a href="./kimi-cheatsheet.html">Cheatsheet</a></li></ul>',25)])])}const f=e(i,[["render",s]]);export{k as __pageData,f as default};
